/* Boss presentation only. Simulation remains the owner of danger geometry and clocks. */
(function(root){'use strict';const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n)),COLORS=['#8eff94','#ffce70','#9beaff','#ff9857','#ff95ef','#be9aff'];
function state(g){const b=g.boss;if(!b)return null;const t=g.time;if(g.practice&&['idle_a','idle_b','charge_a','charge_b','fire','recoil','hurt','weak','defeat'].includes(b.reviewPose))return{key:'inspect',a:b.reviewPose,b:b.reviewPose,mix:0,age:0,label:'◈',color:'#b6dbe7'};const age=t-(b.visualAttack?.at??-100);if(b.hp<=0)return{key:'defeat',a:'defeat',b:'defeat',mix:0,age:g.endFxAge||0,label:'✦',color:'#e9e0ff'};if(b.hurt>0||b.visualHurtUntil>t)return{key:'hurt',a:'hurt',b:'hurt',mix:0,age:Math.max(b.hurt,b.visualHurtUntil-t||0),label:'✦',color:'#fff2c6'};if(b.telegraph){const total=b.telegraph.total||g.level.boss.attacks.find(a=>a.phase===b.phase)?.telegraph||1.2,p=clamp(1-b.telegraph.t/total);return{key:'charge',a:'charge_a',b:'charge_b',mix:p,age:p,label:'!',color:'#ffd275'};}if(age>=0&&age<.18)return{key:'fire',a:'fire',b:'fire',mix:0,age,label:'▼',color:'#ffbb90'};if(age>=.18&&age<.48)return{key:'recoil',a:'fire',b:'recoil',mix:clamp((age-.18)/.18),age,label:'↺',color:'#c4dded'};if(age>=.48&&age<.85)return{key:'recover',a:'recoil',b:g.bossGuarded()?'idle_a':'weak',mix:clamp((age-.48)/.37),age,label:'↺',color:'#b2d4df'};if(g.bossGuarded())return{key:'guard',a:'idle_a',b:'idle_b',mix:(1-Math.cos(t*2.4))*.5,age:0,label:'⬡',color:'#8db6cf'};return{key:'weak',a:'weak',b:'weak',mix:0,age:0,label:'◎',color:'#b8ffe6'};}
function warningShapes(g,t){if(!g.boss||!t)return[];const y=g.boss.y+g.boss.h,rawWidths={root_zone:130,eye_beam:44,scan_beam:56,freeze_paddle:76},zones=Number.isFinite(t.x)&&rawWidths[t.id]?[{x:t.x-rawWidths[t.id]/2,w:rawWidths[t.id]}]:t.zones||[];return zones.map(z=>({...z,y:t.id==='root_zone'?632:t.id==='freeze_paddle'?624:['fruit_drop','sand_bullets','shatter_field'].includes(t.id)?y:350,h:t.id==='root_zone'?40:t.id==='freeze_paddle'?44:['fruit_drop','sand_bullets','shatter_field'].includes(t.id)?666-y:332,kind:['fruit_drop','sand_bullets','shatter_field'].includes(t.id)?'path':t.id==='freeze_paddle'?'lock':'zone'}));}
function color(g){return COLORS[(g.level.region_index||1)-1]||COLORS[5];}function family(id){return /ice|freeze|blizzard/.test(id)?'ice':/flame|lava|swallow/.test(id)?'flame':/scan|drone|portal/.test(id)?'scan':/sand|eye|shield/.test(id)?'solar':/fruit|root|worm/.test(id)?'plasma':'fracture';}
function rect(c,x,y,w,h,col){c.fillStyle=col;c.fillRect(x,y,w,h);}function ring(c,x,y,r,col,w=2){c.strokeStyle=col;c.lineWidth=w;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.stroke();}function fx(c,sprite,type,frame,x,y,w,h=w,alpha=1){c.save();c.globalAlpha*=alpha;sprite(c,'sheet_boss_vfx',type+'_'+clamp(Math.floor(frame),0,3),x-w/2,y-h/2,w,h);c.restore();}
function drawBody(c,g,sprite,reduced=false){const b=g.boss,s=state(g);if(!s)return;const x=b.x+b.w/2,y=b.y+b.h/2,t=g.time,col=color(g),size=212;let dy=0,rot=0;if(!reduced){dy=s.key==='guard'||s.key==='weak'?Math.sin(t*2.4)*2:s.key==='charge'?-3*s.mix:s.key==='fire'?Math.sin(s.age/.18*Math.PI)*-5:s.key==='hurt'?Math.sin(b.hurt*90)*2:0;rot=s.key==='hurt'?Math.sin(b.hurt*80)*.035:0;}c.save();c.translate(x,y+dy);c.rotate(rot);const drawPose=(pose,a)=>{if(a<=.001)return;c.globalAlpha=a;sprite(c,'sheet_boss_motion',b.id+'_'+pose,-size/2,-size/2,size,size);};const mix=reduced?(s.mix>.5?1:0):s.mix;
 if(s.key==='defeat'){c.translate(0,Math.min(8,s.age*8));drawPose('defeat',Math.max(.15,1-s.age*.75));}else{drawPose(s.a,s.a===s.b?1:1-mix);if(s.a!==s.b)drawPose(s.b,mix);}c.globalAlpha=1;
 if(b.clones>0)for(const delta of[-110,110]){const dx=clamp(x+delta,70,410)-x;c.globalAlpha=.22;sprite(c,'sheet_boss_motion',b.id+'_idle_b',dx-56,-56,112,112);}c.globalAlpha=1;
 if(s.key==='guard'){c.strokeStyle='#9bc9e3';c.lineWidth=2;c.setLineDash([11,7]);c.beginPath();c.ellipse(0,0,76,57,reduced?0:t*.35,0,Math.PI*2);c.stroke();c.setLineDash([]);}if(s.key==='weak'){ring(c,0,0,19,'#c6ffe7',2);for(let i=0;i<4;i++){const a=i*Math.PI/2;c.save();c.rotate(a);rect(c,23,-1,7,2,'#c6ffe7');c.restore();}}for(let i=0;i<3;i++){c.strokeStyle=i<b.phase?col:'#3b4f64';c.lineWidth=i<b.phase?3:1;c.beginPath();c.arc(0,0,65,Math.PI*.2+i*.25,Math.PI*.36+i*.25);c.stroke();}
 c.font='bold 13px Arial';c.textAlign='center';c.fillStyle=s.color;c.fillText(s.label,0,-61);if(s.key==='charge'&&!reduced){fx(c,sprite,family(b.telegraph.id),Math.min(2,Math.floor(s.mix*3)),0,26,22+s.mix*25,22+s.mix*25,.65);ring(c,0,25,27-s.mix*13,'#ffe0a0',1.5);}if(s.key==='fire')fx(c,sprite,family(b.visualAttack?.id),1,0,51,49,49,.9);if(s.key==='defeat')fx(c,sprite,['plasma','solar','ice','flame','scan','fracture'][(g.level.region_index||1)-1],s.age/.9*4,0,0,reduced?90:90+s.age*60,100,Math.max(0,1-s.age));c.restore();return s;}
function drawWarnings(c,g,sprite,reduced=false){const b=g.boss,t=b?.telegraph;if(!t)return;const shapes=warningShapes(g,t),p=clamp(1-t.t/(t.total||g.level.boss.attacks.find(a=>a.phase===b.phase)?.telegraph||1.2));for(const z of shapes){c.save();c.beginPath();c.rect(z.x,z.y,z.w,z.h);c.clip();rect(c,z.x,z.y,z.w,z.h,'#ffbe4b19');c.strokeStyle='#ffd17c';c.lineWidth=1.5;c.setLineDash([5,5]);c.strokeRect(z.x+.8,z.y,z.w-1.6,z.h);c.setLineDash([]);for(let y=z.y+10;y<z.y+z.h;y+=28){const yy=y+(reduced?0:g.time*24%28);c.beginPath();c.moveTo(z.x+3,yy);c.lineTo(z.x+z.w/2,yy+7);c.lineTo(z.x+z.w-3,yy);c.stroke();}rect(c,z.x,z.y+z.h-4,z.w*p,4,'#ffe1a5');c.restore();}
 if(!shapes.length){const x=b.x+b.w/2,y=b.y+b.h/2;c.save();c.strokeStyle='#ffd17c';c.setLineDash([4,5]);c.lineWidth=2;c.beginPath();c.ellipse(x,y,82,66,0,0,Math.PI*2);c.stroke();c.setLineDash([]);c.restore();if(t.id==='swallow_ball')for(const ball of g.balls){c.strokeStyle='#ffd17c99';c.beginPath();c.moveTo(ball.x,ball.y);c.lineTo(x,y+40);c.stroke();}}
 c.save();c.font='bold 11px Arial';c.textAlign='center';c.fillStyle='#ffe0a4';c.fillText(shapes.length?'!':'⬡',b.x+b.w/2,b.y+b.h+55);c.restore();}
function drawAttacks(c,g,sprite,reduced=false){const t=g.time;for(const h of g.hazards){const y=h.type==='root'?632:350,hh=h.type==='root'?40:332,id=h.attack||h.type,col=h.type==='lethal'?'#ff8760':h.type==='reverse'?'#f48cff':'#85f5a3';c.save();c.beginPath();c.rect(h.x,y,h.w,hh);c.clip();rect(c,h.x,y,h.w,hh,col+'33');rect(c,h.x,y,1,hh,col);rect(c,h.x+h.w-1,y,1,hh,col);if(h.type!=='root'){rect(c,h.x+h.w*.42,y,h.w*.16,hh,'#fff1d2');if(!reduced){fx(c,sprite,family(id),Math.floor(t*12)%3,h.x+h.w/2,y+hh/2,h.w*1.6,hh,.7);}}else fx(c,sprite,'plasma',Math.floor(t*10)%3,h.x+h.w/2,y+20,h.w,50,.8);c.restore();}
 for(const shot of g.shots){const col=shot.effect==='lethal'?'#ffad86':shot.effect==='slow'?'#ffdf8d':'#98ffab';if(!reduced){c.strokeStyle=col+'99';c.lineWidth=3;c.beginPath();c.moveTo(shot.x,shot.y);c.lineTo(shot.x-shot.vx*.08,shot.y-21);c.stroke();}fx(c,sprite,family(shot.attack||'fruit_drop'),Math.floor(t*12)%3,shot.x,shot.y,shot.r*3,shot.r*3,1);ring(c,shot.x,shot.y,shot.r,col,1);}
 const last=g.boss?.visualAttack;if(last){const age=t-last.at;if(age>=0&&age<.65&&last.id==='freeze_paddle')fx(c,sprite,'ice',age/.65*4,last.x,642,82,64,1-age/.9);}
 for(const b of g.bricks){const age=t-(b.born??-100);if(age>=0&&age<.6)fx(c,sprite,family(b.attack),age/.6*4,b.x+b.w/2,b.y+b.h/2,b.w+10,b.h+18,reduced?.5:.8);}
 if(!reduced)for(const b of g.blockers){const age=t-(b.born??-100);if(age>=0&&age<.6)fx(c,sprite,family(b.attack),age/.6*4,b.x+b.w/2,b.y+b.h/2,70,70,1-age);}}
const api={state,warningShapes,drawBody,drawWarnings,drawAttacks,family};root.BossPresentation=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
